package ociresources

import (
	"fmt"

	tea "github.com/charmbracelet/bubbletea"
)

// Rows an action is running on, across the four tabs (§3.22).
//
// Every action here is a `docker` invocation that can take seconds — removing a
// large image, a network the daemon is still tearing connections off, a
// `docker login` that has to reach a registry over a slow link. Nothing said so:
// the row was identical to one with nothing happening to it.
//
// Each table spends a different cell on the spinner, and the choice is the same
// each time: the one the user does not need while the action runs. §3.16 settled
// why it is a cell and not a column of its own — a column costs cells on every
// screen to say nothing on all but one row, and at 80 columns this view has none
// to spare.

// busyMessage is what every tab says when an action is already running on the
// selected row. One message rather than one per verb, because the user's next
// move is the same in all of them: wait.
const busyMessage = "Already busy — an action is running on this row"

// advanceBusySpinners moves every table's frame on and reports whether anything
// is running. It is called from the spinner tick, which is what keeps the frames
// turning; the tick has to go on being scheduled while this returns true, or the
// spinner stops on a row that is still working.
func (m *Model) advanceBusySpinners() bool {
	m.imageTable.AdvanceSpinner()
	m.networkTable.AdvanceSpinner()
	m.volumeTable.AdvanceSpinner()
	m.registryTable.AdvanceSpinner()
	return len(m.busyLabels()) > 0
}

// busyLabels gathers what is running across every tab.
//
// Across all four rather than the active one: an action started on the Images
// tab goes on running after `tab`, and a spinner that stopped turning because
// the user looked elsewhere would read as a hang on the way back.
func (m Model) busyLabels() []string {
	var out []string
	out = append(out, m.imageTable.BusyLabels()...)
	out = append(out, m.networkTable.BusyLabels()...)
	out = append(out, m.volumeTable.BusyLabels()...)
	out = append(out, m.registryTable.BusyLabels()...)
	return out
}

// actionLine names what is running, in words. The spinner on the row says that
// something is; this says what.
//
// Rendered from the current state rather than assigned to a footer message,
// because a footer message expires after three seconds (Rule 128) and these
// outlive that — the same reason §3.17's sync progress is a rendered line.
func (m Model) actionLine() string {
	if m.pruning != "" {
		return "Pruning " + m.pruning + "…"
	}
	labels := m.busyLabels()
	switch len(labels) {
	case 0:
		return ""
	case 1:
		return labels[0] + "…"
	default:
		// Naming them all would run past the line; the count is what the user
		// is waiting on anyway.
		return fmt.Sprintf("%d actions running…", len(labels))
	}
}

// busyTick is what an action returns alongside its command so the frames turn.
// Init starts a tick, but it stops as soon as nothing is loading, and an action
// begun after that would sit on a frozen frame.
func (m Model) busyTick() tea.Cmd { return m.spinner.Tick }
package ociresources

import (
	"slices"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/docker"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/registryalias"
)

// What is being scanned is the registry's answer, not this view's (§3.58).
//
// It held a `scanningImages` map and a `scanning` bool derived from it, and both
// knew only what this view had launched. An image scanned from `:sec` — the same
// image, the same cache entry — went unnoticed here, so `S` offered itself on a
// row already being scanned and the two wrote the same file.
//
// The view's own `spinner.Model` stays, and deliberately: it animates *loading*
// — the image list, the networks, a `docker` action on a row — and a load is not
// a job. What moved is the frame the scan cells use, which now comes from the
// one chain the router holds (D5).

// handleJobsChanged takes the router's snapshot. It is the only writer of the
// two fields.
func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
	m.jobs = msg.Runs
	m.failures = slices.Clone(msg.Failures)
	m.contextName = msg.Context
	// The footer's spinner is deliberately not touched: here it belongs to
	// *loading* — a tab reading its list — and this view's scan progress is on
	// the rows, not in the footer. Two writers of one field would fight every
	// frame a scan and a load overlapped.
	m.updateImageTable()
	if m.registryBrowser != nil {
		m.registryBrowser.SetTagScanningSet(m.scanningNames())
	}
	return m, nil
}

// handleFrameMsg takes the animation's frame for the scan cells. The footer is
// untouched, for the reason handleJobsChanged gives.
func (m Model) handleFrameMsg(msg jobs.FrameMsg) (tea.Model, tea.Cmd) {
	m.jobFrame = msg.Frame
	m.updateImageTable()
	return m, nil
}

// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
func (m Model) scanRun(names []string) jobs.Run {
	run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
	// The alias is applied here rather than by whoever shows the run: it is
	// this view's configuration that defines it, and `:jobs` has no business
	// reading a registry list to print a name.
	aliases := registryalias.From(m.registries)
	for _, name := range names {
		if display := docker.ApplyAliases(name, aliases); display != name {
			run = run.WithDisplay(name, display)
		}
	}
	return run
}

// scanningImage reports whether an image is queued or being scanned, whoever
// started it.
func (m Model) scanningImage(name string) bool {
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindScan {
			continue
		}
		for _, item := range run.Items {
			if item.Target == name && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}

// scanningNames lists every image with a scan in flight, for the registry
// browser, which decorates its tag rows from the same source.
func (m Model) scanningNames() map[string]bool {
	out := make(map[string]bool)
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindScan {
			continue
		}
		for _, item := range run.Items {
			if !item.State.Terminal() {
				out[item.Target] = true
			}
		}
	}
	return out
}

// anyScanRunning reports whether a scan is going anywhere. It is what A and
// ctrl+a refuse on, and it is true for a scan this view did not start — which
// is the point: the two would write the same cache entries.
func (m Model) anyScanRunning() bool { return len(m.scanningNames()) > 0 }

// pullRun builds the run behind a registry-browser pull.
func (m Model) pullRun(name string) jobs.Run {
	run := jobs.NewRun(jobs.KindPull, command.ViewOCIResources, "", "images", name)
	aliases := registryalias.From(m.registries)
	if display := docker.ApplyAliases(name, aliases); display != name {
		run = run.WithDisplay(name, display)
	}
	return run
}

// pullingImage reports whether a pull for name is queued or running.
func (m Model) pullingImage(name string) bool {
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindPull {
			continue
		}
		for _, item := range run.Items {
			if item.Target == name && !item.State.Terminal() {
				return true
			}
		}
	}
	return false
}

// pullingNames lists every image with a pull in flight, for imageRows —
// which is what shows a placeholder row for an image not pulled before.
func (m Model) pullingNames() map[string]bool {
	out := make(map[string]bool)
	for _, run := range jobs.Unfinished(m.jobs) {
		if run.Kind != jobs.KindPull {
			continue
		}
		for _, item := range run.Items {
			if !item.State.Terminal() {
				out[item.Target] = true
			}
		}
	}
	return out
}

// ── What each message tells the registry (jobs.Reporter) ─────────────────────

func (m ImageScanStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m ImageScanFinishedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

func (m RegistryPullStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m RegistryPullCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemDone}
	switch {
	case len(m.InUse) > 0:
		t.State = jobs.ItemFailed
		t.Detail = "not updated — the image is in use"
	case isBlocked(m.Err):
		// The reason, not "check logs": it names the rule, and it is what an
		// agent that asked for the pull reads (§3.82).
		t.State = jobs.ItemFailed
		t.Detail = "refused — " + m.Err.Error()
	case m.Err != nil:
		t.State = jobs.ItemFailed
		t.Detail = "pull failed — check logs"
	}
	return t
}

// Compile-time proof that every progress message can be applied. One added
// without a transition would leave its row spinning for the life of the view.
var (
	_ jobs.Reporter = ImageScanStartingMsg{}
	_ jobs.Reporter = ImageScanFinishedMsg{}
	_ jobs.Reporter = RegistryPullStartingMsg{}
	_ jobs.Reporter = RegistryPullCompleteMsg{}
)
	ContainerID string
	Err         error
}

// New creates a new OCI resources view
func New(cfg *config.Config) Model {
	s := spinner.New()
	s.Spinner = spinner.Dot
	s.Style = theme.SpinnerStyle()

	it := datatable.New(datatable.Config[imageRow]{
		Columns:    imageColumns(cfg.Scan.Categories.Misconfig.Enabled),
		SortColumn: imageColumnName,
		// A pulling placeholder row carries no Image yet, so its ID is empty —
		// falling back to the name keeps two concurrent pulls from colliding
		// on the same key.
		Key: func(r imageRow) string {
			if r.Image.ID == "" {
				return "pull:" + r.RawName
			}
			return r.Image.ID
		},
		// The ID cell, not a column of its own. §3.16 settled that argument for
		// the clone checkbox: a column costs cells on every screen to say
		// nothing on all but one row, and at 80 columns this view has none to
		// spare. The ID is the cell to spend — it neither sorts nor searches,
		// twelve hex characters being nothing anyone orders or looks for, and
		// it is not what the user is watching while the image is removed.
		StatusColumn: imageColumnID,
	})

	nt := datatable.New(datatable.Config[docker.Network]{
		Columns:      networkColumns(),
		SortColumn:   -1,
		Key:          func(n docker.Network) string { return n.ID },
		StatusColumn: networkColumnID,
	})
	nt.Blur()

	vt := datatable.New(datatable.Config[docker.Volume]{
		Columns:    volumeColumns(),
		SortColumn: -1,
		// A volume has no ID: its name is its identity, which is also why the
		// spinner cannot go there — it is the one cell that says which row this
		// is. Driver is the expendable one, and it reads "local" on very nearly
		// every volume there has ever been.
